export async function renderChampionship(root, id) {
  root.innerHTML = `<div class="shell"><header class="topbar"><a class="logo" href="/" data-link>ARENA</a><button class="btn ghost" data-back>← Meus campeonatos</button></header><main class="section"><div class="card">Carregando campeonato...</div></main></div>`;
  root.querySelector('[data-back]').onclick = () => navigate('/');
  try {
    const championship = await getChampionship(id);
    if (!championship) throw new Error('Campeonato não encontrado.');
    mount(root, championship);
  } catch (error) { root.querySelector('main').innerHTML = `<div class="card"><h2>Não foi possível abrir</h2><p class="muted">${esc(error.message || error)}</p><button class="btn ghost" data-back>← Voltar</button></div>`; root.querySelector('[data-back]').onclick = () => navigate('/'); }
}

function mount(root, initial) {
  let state = clone(initial); let tab = 'overview'; let registrations = []; let auditRows = [];
  let superadmin = false; isSuperadmin().then((v) => { superadmin = v; }).catch(() => {});
  ensureCategories(state);
  loadCategoryIntoRoot(state, activeCategory(state));
  ensureOps(state);
  const accent = state.branding?.accent || '#2fcf6b';
  root.querySelector('main').innerHTML = `<div class="championship-shell" style="--championship-accent:${accent}"><div class="championship-heading"><div><button class="btn ghost sm" data-back>← Meus campeonatos</button><small>${esc(state.formato || 'liga').toUpperCase()}</small><h1>${esc(state.nome)}</h1><p class="muted">${esc(state.subtitulo || 'Organize sua competição em um só lugar.')}</p></div><div class="actions"><button class="btn" data-pdf>Baixar relatório</button><span class="tag" data-save>Salvo</span><span class="tag">${esc(roleLabel(state, auth.currentUser))}</span></div></div><div data-categorybar></div><nav class="championship-tabs">${[['overview','Visão geral'],['categorias','Categorias'],['fases','Fases'],['jogos','Jogos'],['chave','Chaveamento'],['classif','Tabela'],['equipes','Equipes'],['artilharia','Artilharia'],['disciplina','Disciplina'],['inscricoes','Inscrições'],['publicacao','Publicação'],['historico','Histórico'],['gerenciamento','Gerenciamento'],['config','Configurações']].map(([key,label]) => `<button data-tab="${key}">${label}</button>`).join('')}</nav><section data-content></section></div>`;
  const shell = root.querySelector('.championship-shell'); const content = root.querySelector('[data-content]');
  root.querySelector('[data-back]').onclick = () => navigate('/');
  root.querySelectorAll('[data-tab]').forEach((button) => button.onclick = async () => { tab = button.dataset.tab; if (tab === 'inscricoes') { try { registrations = await listRegistrations(state.id); } catch { registrations = []; } } if (tab === 'historico') { try { auditRows = await listAudit(state.id); } catch { auditRows = []; } } render(); });
  async function persist() { if (!superadmin && !can(state, auth.currentUser, 'results') && !can(state, auth.currentUser, 'registrations') && !can(state, auth.currentUser, 'admin')) { toast('Seu perfil não tem permissão para esta ação.'); return; } root.querySelector('[data-save]').textContent = 'Salvando...'; saveRootIntoActive(state); state.updated = Date.now(); try { await saveChampionship(state); root.querySelector('[data-save]').textContent = 'Salvo'; } catch (error) { root.querySelector('[data-save]').textContent = 'Erro ao salvar'; toast(error.message || 'Não foi possível salvar.'); } }
  function render() { root.querySelectorAll('[data-tab]').forEach((button) => button.classList.toggle('active', button.dataset.tab === tab)); root.querySelector('[data-categorybar]').innerHTML = categoryBar(); content.innerHTML = tab === 'overview' ? overview() : tab === 'categorias' ? categoriesView() : tab === 'fases' ? fasesView() : tab === 'jogos' ? games() : tab === 'chave' ? bracketView() : tab === 'classif' ? standings() : tab === 'equipes' ? teams() : tab === 'artilharia' ? scorersView() : tab === 'disciplina' ? disciplineView() : tab === 'inscricoes' ? registrationsView() : tab === 'publicacao' ? '<div class="card"><h2>Publicação</h2><p class="muted">Copie os links públicos para divulgar o campeonato.</p><button class="btn primary" data-publication>Abrir central de publicação</button></div>' : tab === 'gerenciamento' ? managementView() : tab === 'historico' ? auditView() : config(); bind(); }
  function categoryBar() { if (!state.categories || state.categories.length < 2) return ''; return `<div class="catbar">${state.categories.map((category) => `<button class="catpill ${category.id === state.activeCategoryId ? 'active' : ''}" data-category="${esc(category.id)}">${esc(category.nome)}</button>`).join('')}</div>`; }
  function categoriesView() { return `<div class="card"><div class="actions" style="justify-content:space-between"><div><h2>Categorias</h2><p class="muted">Separe atletas e jogos por categoria (ex.: sub-15, feminino).</p></div><button class="btn primary" data-add-category>+ Adicionar categoria</button></div><div style="margin-top:18px">${state.categories.map((category) => `<div class="team-row"><span>${category.id === state.activeCategoryId ? '●' : ''}</span><input data-category-name="${esc(category.id)}" value="${esc(category.nome)}">${state.categories.length > 1 ? `<button class="btn ghost" data-remove-category="${esc(category.id)}">Remover</button>` : ''}</div>`).join('')}</div></div>`; }
  function fasesView() { const category = activeCategory(state); const phases = category.phases || []; return `<div class="card"><div class="actions" style="justify-content:space-between"><div><h2>Fases</h2><p class="muted">Configure o formato da disputa e a passagem automática dos classificados para a próxima fase.</p></div><button class="btn primary" data-add-phase>+ Nova fase</button></div><div style="margin-top:18px">${phases.map((phase, pi) => { const later = phases.filter((_, i) => i > pi); const prog = phase.progression || {}; const participantsCount = (phase.participantTeamIds && phase.participantTeamIds.length) || (state.teams || []).length; return `<div style="padding:14px 0;border-bottom:1px solid var(--line)"><div class="row" style="flex-wrap:wrap"><input data-phase-name="${esc(phase.id)}" value="${esc(phase.nome)}" style="flex:1;min-width:180px;font-weight:700"><select data-phase-format="${esc(phase.id)}">${PHASE_FORMATS.map(([key, label]) => `<option value="${key}" ${phase.formato === key ? 'selected' : ''}>${esc(label)}</option>`).join('')}</select><input type="number" min="1" max="2" data-phase-turnos="${esc(phase.id)}" value="${phase.cfg?.turnos || 1}" style="width:60px" title="Turnos">${phase.formato === 'grupos' ? `<input type="number" min="1" data-phase-ngrupos="${esc(phase.id)}" value="${phase.cfg?.nGrupos || 2}" style="width:60px" title="Grupos">` : ''}${phase.formato === 'mata' ? `<label class="muted" style="display:flex;align-items:center;gap:4px"><input type="checkbox" style="display:inline;width:auto;margin-top:0" data-phase-mao-unica="${esc(phase.id)}" ${phase.cfg?.maoUnica ? 'checked' : ''}> Mão única</label><label class="muted" style="display:flex;align-items:center;gap:4px"><input type="checkbox" style="display:inline;width:auto;margin-top:0" data-phase-terceiro="${esc(phase.id)}" ${phase.cfg?.terceiro !== false ? 'checked' : ''}> 3º lugar</label>` : ''}<span class="muted">${phase.status === 'andamento' ? 'Em andamento' : 'Planejada'} · ${(phase.matches || []).length} jogos · ${participantsCount} participantes</span><button class="btn ghost sm" data-switch-phase="${esc(phase.id)}">Abrir</button>${phase.id === category.activePhaseId ? `<button class="btn primary sm" data-generate-phase>Gerar/Refazer</button>` : ''}${phases.length > 1 ? `<button class="btn ghost sm" data-remove-phase="${esc(phase.id)}">Excluir</button>` : ''}</div>${later.length ? `<div class="row" style="flex-wrap:wrap;margin-top:10px"><select data-progress-target="${esc(phase.id)}"><option value="">Progressão não configurada</option>${later.map((t) => `<option value="${esc(t.id)}" ${prog.targetPhaseId === t.id ? 'selected' : ''}>→ ${esc(t.nome)}</option>`).join('')}</select><select data-progress-mode="${esc(phase.id)}"><option value="overall" ${prog.mode !== 'perGroup' ? 'selected' : ''}>Melhores no geral</option>${phase.formato === 'grupos' ? `<option value="perGroup" ${prog.mode === 'perGroup' ? 'selected' : ''}>Melhores de cada grupo</option>` : ''}</select><input type="number" min="1" data-progress-count="${esc(phase.id)}" value="${prog.count || 2}" style="width:70px"><span class="muted">${esc(progressionSummary(category, phase))}</span>${prog.targetPhaseId ? `<button class="btn primary sm" data-apply-progress="${esc(phase.id)}">Classificar →</button>` : ''}</div>` : ''}</div>`; }).join('')}</div></div>`; }
  function overview() { const matches = state.matches || []; const finished = matches.filter((m) => m.hg != null && m.ag != null).length; return `<div class="grid"><div class="card"><small>PROGRESSO</small><h2>${finished}/${matches.length || 0}</h2><p class="muted">jogos encerrados</p></div><div class="card"><small>EQUIPES</small><h2>${(state.teams || []).length}</h2><p class="muted">participantes cadastrados</p></div><div class="card"><small>STATUS</small><h2>${esc(state.status || 'Rascunho')}</h2><p class="muted">situação do campeonato</p></div></div><div class="card" style="margin-top:16px"><h2>Próximos passos</h2><p class="muted">Cadastre equipes, organize os jogos e lance os placares. A tabela será recalculada automaticamente.</p><div class="actions"><button class="btn primary" data-jump="equipes">Cadastrar equipes</button><button class="btn" data-jump="jogos">Ver jogos</button></div></div>`; }
  function teams() { return `<div class="card"><div class="actions" style="justify-content:space-between"><div><h2>Equipes</h2><p class="muted">Edite os nomes das equipes participantes.</p></div><button class="btn primary" data-add-team>+ Adicionar equipe</button></div><div style="margin-top:18px">${(state.teams || []).map((team, index) => `<div class="team-row">${team.logo ? `<img class="miniphoto" data-pick-logo="${esc(team.id)}" src="${team.logo}" style="width:28px;height:28px;border-radius:5px;object-fit:cover;cursor:pointer">` : `<span data-pick-logo="${esc(team.id)}" style="cursor:pointer">${index + 1}</span>`}<input data-team="${esc(team.id)}" value="${esc(team.nome)}"><button class="btn ghost" data-roster="${esc(team.id)}">Elenco (${(team.roster || []).length})</button><button class="btn ghost" data-remove-team="${esc(team.id)}">Remover</button></div>`).join('') || '<p class="muted">Nenhuma equipe cadastrada.</p>'}</div><button class="btn primary" style="margin-top:18px" data-save-teams>Salvar equipes</button></div>`; }
  function rosterModal(teamId) { const team = teamById(state, teamId); if (!team) return; team.roster = team.roster || []; modal(`<h3>Elenco — ${esc(team.nome)}</h3><div style="margin-top:12px">${team.roster.map((athlete) => `<div class="ath-row"><span>${athlete.foto ? `<img class="miniphoto" src="${athlete.foto}" style="width:28px;height:28px;border-radius:50%;object-fit:cover">` : '👤'}</span><input data-athlete-name="${esc(athlete.id)}" value="${esc(athlete.nome)}" placeholder="Nome" style="flex:1"><input type="number" data-athlete-numero="${esc(athlete.id)}" value="${esc(athlete.numero || '')}" placeholder="Nº" style="width:70px"><button class="btn ghost sm" data-athlete-photo="${esc(athlete.id)}">📷</button><button class="btn ghost sm" data-athlete-remove="${esc(athlete.id)}">🗑</button></div>`).join('') || '<p class="muted">Nenhum atleta cadastrado.</p>'}</div><h3 style="margin-top:18px">Comissão técnica</h3><div style="margin-top:8px">${STAFF_ROLES.map(([key, label]) => `<div class="row" style="padding:8px 0;border-bottom:1px solid var(--line)"><span style="flex:1">${esc(label)}</span><input data-staff="${esc(team.id)}:${key}" value="${esc((team.staff || {})[key] || '')}" placeholder="Nome" style="flex:1"></div>`).join('')}</div><div class="row" style="margin-top:12px;gap:8px"><input data-new-athlete-name placeholder="Nome do novo atleta" style="flex:1"><button class="btn primary" data-add-athlete="${esc(team.id)}">+ Adicionar</button></div><div class="row" style="justify-content:flex-end;margin-top:14px"><button class="btn ghost" data-close-modal>Fechar</button></div>`); const box = document.getElementById('modalBox'); box.querySelector('[data-close-modal]').onclick = () => closeModal(); box.querySelectorAll('[data-athlete-name]').forEach((input) => input.onchange = async () => { const result = updateAthlete(team, input.dataset.athleteName, { nome: input.value, numero: box.querySelector(`[data-athlete-numero="${input.dataset.athleteName}"]`).value }); if (!result.ok) return; await persist(); await addAudit(state.id, 'athlete_updated', 'Atleta atualizado'); render(); }); box.querySelectorAll('[data-athlete-numero]').forEach((input) => input.onchange = async () => { const result = updateAthlete(team, input.dataset.athleteNumero, { nome: box.querySelector(`[data-athlete-name="${input.dataset.athleteNumero}"]`).value, numero: input.value }); if (!result.ok) return; await persist(); await addAudit(state.id, 'athlete_updated', 'Atleta atualizado'); render(); }); box.querySelectorAll('[data-athlete-remove]').forEach((button) => button.onclick = async () => { const result = removeAthlete(team, button.dataset.athleteRemove); if (!result.ok) return; await persist(); await addAudit(state.id, 'athlete_removed', 'Atleta removido'); rosterModal(teamId); }); box.querySelectorAll('[data-athlete-photo]').forEach((button) => button.onclick = () => { const input = document.createElement('input'); input.type = 'file'; input.accept = 'image/*'; input.onchange = async () => { const file = input.files[0]; if (!file) return; const dataUrl = await compressPhoto(file); if (!dataUrl) return toast('Falha na imagem'); const result = setAthletePhoto(team, button.dataset.athletePhoto, dataUrl); if (!result.ok) return; await persist(); rosterModal(teamId); }; input.click(); }); const addButton = box.querySelector('[data-add-athlete]'); if (addButton) addButton.onclick = async () => { const nameInput = box.querySelector('[data-new-athlete-name]'); const result = addAthlete(team, { nome: nameInput.value }); if (!result.ok) return toast(result.reason); await persist(); await addAudit(state.id, 'athlete_added', `Atleta adicionado: ${result.athlete.nome}`); rosterModal(teamId); }; box.querySelectorAll('[data-staff]').forEach((input) => input.onchange = async () => { const [staffTeamId, key] = input.dataset.staff.split(':'); const result = setTeamStaff(teamById(state, staffTeamId), key, input.value); if (!result.ok) return; await persist(); render(); }); }
  function matchOpsModal(matchId) { const match = (state.matches || []).find((m) => m.id === matchId); if (!match) return; const meta = matchMeta(match); const home = state.teams?.[match.home]?.nome || 'A definir'; const away = state.teams?.[match.away]?.nome || 'A definir'; modal(`<h3>Dados da partida</h3><p class="muted">${esc(home)} × ${esc(away)}</p><div class="row" style="flex-wrap:wrap;margin-top:12px"><input type="date" data-op-date value="${esc(meta.date || '')}" style="flex:1;min-width:140px"><input type="time" data-op-time value="${esc(meta.time || '')}" style="flex:1;min-width:100px"></div><div class="row" style="flex-wrap:wrap;margin-top:10px"><select data-op-venue style="flex:1;min-width:160px"><option value="">Local — selecionar</option>${(state.venues || []).map((v) => `<option value="${esc(v.id)}" ${meta.venueId === v.id ? 'selected' : ''}>${esc(v.name)}</option>`).join('')}</select><select data-op-status style="flex:1;min-width:140px">${[['scheduled', 'Agendada'], ['live', 'Em andamento'], ['finished', 'Encerrada'], ['postponed', 'Adiada'], ['cancelled', 'Cancelada']].map(([key, label]) => `<option value="${key}" ${(meta.status || 'scheduled') === key ? 'selected' : ''}>${esc(label)}</option>`).join('')}</select></div><div class="row" style="flex-wrap:wrap;margin-top:10px"><select data-op-referee style="flex:1;min-width:160px"><option value="">Árbitro — selecionar</option>${(state.officials || []).map((o) => `<option value="${esc(o.id)}" ${meta.refereeId === o.id ? 'selected' : ''}>${esc(o.name)}</option>`).join('')}</select><select data-op-table style="flex:1;min-width:160px"><option value="">Mesário — selecionar</option>${(state.officials || []).map((o) => `<option value="${esc(o.id)}" ${meta.tableOfficialId === o.id ? 'selected' : ''}>${esc(o.name)}</option>`).join('')}</select></div><textarea data-op-notes placeholder="Observações" style="width:100%;min-height:70px;margin-top:10px;border:1px solid var(--line);background:var(--surface-muted);color:var(--text);border-radius:8px;padding:10px">${esc(meta.notes || '')}</textarea><div class="row" style="justify-content:flex-end;margin-top:14px"><button class="btn ghost" data-close-modal>Cancelar</button><button class="btn primary" data-save-match-ops="${esc(matchId)}">Salvar</button></div>`); const box = document.getElementById('modalBox'); box.querySelector('[data-close-modal]').onclick = () => closeModal(); box.querySelector('[data-save-match-ops]').onclick = async () => { const result = saveMatchOps(state, matchId, { date: box.querySelector('[data-op-date]').value, time: box.querySelector('[data-op-time]').value, venueId: box.querySelector('[data-op-venue]').value, refereeId: box.querySelector('[data-op-referee]').value, tableOfficialId: box.querySelector('[data-op-table]').value, status: box.querySelector('[data-op-status]').value, notes: box.querySelector('[data-op-notes]').value }); if (!result.ok) return; await persist(); await addAudit(state.id, 'match_updated', `Dados da partida alterados: ${home} × ${away}`, result.before, result.after); closeModal(); render(); }; }
  function games() { if (state.formato === 'mata') return `<div class="card"><p class="muted">Esta fase usa chaveamento. Veja e registre os placares na aba "Chaveamento".</p></div>`; return `<div class="card"><div class="actions" style="justify-content:space-between"><div><h2>Jogos</h2><p class="muted">Registre os placares das partidas.</p></div><button class="btn" data-generate>Gerar tabela</button></div><div style="margin-top:18px">${(state.matches || []).map((match) => { const home = state.teams?.[match.home]?.nome || 'A definir'; const away = state.teams?.[match.away]?.nome || 'A definir'; const line = metaLine(state, match); const status = matchMeta(match).status; const statusText = status === 'live' ? 'AO VIVO' : status === 'postponed' ? 'Adiada' : status === 'cancelled' ? 'Cancelada' : ''; return `<div class="game-row"><strong>${esc(home)}</strong><input type="number" min="0" data-score="${match.id}:hg" value="${match.hg ?? ''}"><span>×</span><input type="number" min="0" data-score="${match.id}:ag" value="${match.ag ?? ''}"><strong>${esc(away)}</strong></div><div class="row" style="flex-wrap:wrap;padding:2px 0 12px"><span class="muted" style="flex:1">${statusText ? `<strong>${statusText}</strong> · ` : ''}${esc(line)}</span><button class="btn ghost sm" data-match-ops="${esc(match.id)}">Dados da partida</button></div>`; }).join('') || '<p class="muted">Nenhum jogo gerado ainda.</p>'}</div></div>`; }
  function roundLabel(size) { return { 2: 'Final', 4: 'Semifinal', 8: 'Quartas de final', 16: 'Oitavas de final', 32: '16-avos' }[size] || `${size}-avos`; }
  function tieRow(tie) { const homeName = tie.a != null ? esc(teamNameById(state, tie.a) || '—') : 'A definir'; const awayName = tie.b != null ? esc(teamNameById(state, tie.b) || '—') : 'A definir'; const canScore = tie.a != null && tie.b != null; const single = !!state.cfg?.maoUnica; const winnerText = tie.winner != null ? ` <span class="muted">· vencedor: ${esc(teamNameById(state, tie.winner) || '—')}</span>` : ''; const showPen = canScore && tie.ag1 != null && tie.bg1 != null && (single || (tie.ag2 != null && tie.bg2 != null)); return `<div class="row" style="flex-wrap:wrap;padding:8px 0;border-bottom:1px solid var(--line)"><span style="flex:1">${homeName} <span class="muted">×</span> ${awayName}${winnerText}</span>${canScore ? `<input type="number" min="0" data-tie-score="${tie.id}:ag1" value="${tie.ag1 ?? ''}" style="width:50px" title="Placar 1ª perna — ${homeName}"><input type="number" min="0" data-tie-score="${tie.id}:bg1" value="${tie.bg1 ?? ''}" style="width:50px" title="Placar 1ª perna — ${awayName}">${!single ? `<input type="number" min="0" data-tie-score="${tie.id}:ag2" value="${tie.ag2 ?? ''}" style="width:50px" title="Placar 2ª perna — ${homeName}"><input type="number" min="0" data-tie-score="${tie.id}:bg2" value="${tie.bg2 ?? ''}" style="width:50px" title="Placar 2ª perna — ${awayName}">` : ''}${showPen ? `<input type="number" min="0" data-tie-score="${tie.id}:apen" value="${tie.apen ?? ''}" style="width:50px" title="Pênaltis — ${homeName}"><input type="number" min="0" data-tie-score="${tie.id}:bpen" value="${tie.bpen ?? ''}" style="width:50px" title="Pênaltis — ${awayName}">` : ''}` : ''}</div>`; }
  function bracketView() {
    if (state.formato === 'grupos') {
      if (!(state.grupos || []).length) return `<div class="card"><p class="muted">Gere os jogos da fase primeiro, na aba "Fases".</p></div>`;
      if (!state.bracket) return `<div class="card"><p class="muted" style="margin-bottom:14px">Gere o mata-mata cruzando os classificados de cada grupo.</p><button class="btn primary" data-gen-cross>⚔️ Gerar mata-mata</button></div>`;
    } else if (state.formato !== 'mata') {
      return `<div class="card"><p class="muted">Esta fase não usa chaveamento. Troque o formato da fase ativa para "Mata-Mata" na aba Fases.</p></div>`;
    }
    if (!state.bracket) return `<div class="card"><p class="muted">Nenhum chaveamento gerado ainda. Use "Gerar/Refazer" na aba Fases.</p></div>`;
    advanceBracket(state.bracket, state.cfg);
    const rounds = state.bracket.rounds;
    return `<div class="card">${state.formato === 'grupos' ? '<div class="actions" style="justify-content:flex-end;margin-bottom:8px"><button class="btn ghost sm" data-regen-cross>↺ Regerar</button></div>' : ''}<h2>Chaveamento</h2><div class="bracket-cols">${rounds.map((round) => `<div class="bcol"><h3 class="muted">${roundLabel(round.length * 2)}</h3>${round.map((tie) => tieRow(tie)).join('')}</div>`).join('')}${state.bracket.third ? `<div class="bcol"><h3 class="muted">Disputa de 3º lugar</h3>${tieRow(state.bracket.third)}</div>` : ''}</div></div>`;
  }
  function standingsTableHTML(st, highlight) {
    const showDisc = !!(state.cfg && state.cfg.criterios && state.cfg.criterios.includes('DISC'));
    return `<div class="table-wrap"><table><thead><tr><th>#</th><th>Equipe</th><th>P</th><th>J</th><th>V</th><th>E</th><th>D</th><th>GP</th><th>GC</th><th>SG</th><th>%</th>${showDisc ? '<th>DISC</th>' : ''}</tr></thead><tbody>${st.map((s, i) => `<tr${highlight && i < highlight ? ' style="background:var(--surface-muted)"' : ''}><td>${i + 1}</td><td><strong>${esc(state.teams[s.team].nome)}</strong></td><td>${s.P}</td><td>${s.J}</td><td>${s.V}</td><td>${s.E}</td><td>${s.D}</td><td>${s.GP}</td><td>${s.GC}</td><td>${s.SG > 0 ? '+' : ''}${s.SG}</td><td>${s.pct.toFixed(1)}</td>${showDisc ? `<td>${s.DISC}</td>` : ''}</tr>`).join('')}</tbody></table></div>`;
  }

  function standings() {
    if (state.formato === 'mata') return `<div class="card"><p class="muted">Esta fase usa chaveamento. Veja e registre os placares na aba "Chaveamento".</p></div>`;
    const criteriaLine = `<p class="muted" style="margin:0 0 12px;font-size:13px">Desempate: ${(state.cfg?.criterios || ['P', 'V', 'SG', 'GP']).map((c) => CRIT_LABEL[c] || c).join(' › ')}${state.cfg?.confrontoDireto !== false && !(state.cfg?.criterios || []).includes('CD') ? ' › Confronto direto' : ''}</p>`;
    if (state.formato === 'grupos') {
      if (!(state.grupos || []).length) return `<div class="card"><p class="muted">Nenhum grupo gerado ainda.</p></div>`;
      return state.grupos.map((group, gi) => {
        const idxs = group.map((id) => state.teams.findIndex((t) => t.id === id)).filter((i) => i >= 0);
        const st = computeStandings(state.teams, idxs, (state.matches || []).filter((m) => m.grupo === gi), state.cfg || {});
        return `<div class="card" style="margin-top:${gi ? '16px' : '0'}"><h2>Grupo ${String.fromCharCode(65 + gi)}</h2>${standingsTableHTML(st, state.cfg?.classificam || 2)}</div>`;
      }).join('');
    }
    if (state.formato === 'gxg') {
      const A = (state.grupos?.[0] || []).map((id) => state.teams.findIndex((t) => t.id === id)).filter((i) => i >= 0);
      const B = (state.grupos?.[1] || []).map((id) => state.teams.findIndex((t) => t.id === id)).filter((i) => i >= 0);
      const stA = computeStandings(state.teams, A, state.matches || [], state.cfg || {});
      const stB = computeStandings(state.teams, B, state.matches || [], state.cfg || {});
      return `<div class="card"><h2>Grupo A</h2>${standingsTableHTML(stA, 0)}</div><div class="card" style="margin-top:16px"><h2>Grupo B</h2>${standingsTableHTML(stB, 0)}</div>`;
    }
    const st = computeStandings(state.teams || [], (state.teams || []).map((_, i) => i), state.matches || [], state.cfg || {});
    return `<div class="card"><h2>Tabela de classificação</h2>${criteriaLine}${standingsTableHTML(st, 0)}</div>`;
  }

  function scorersView() {
    const rows = scorerRanking(state);
    if (!rows.length) return `<div class="card"><p class="muted">Nenhum gol registrado ainda.</p></div>`;
    return `<div class="card"><h2>Artilharia</h2><div class="table-wrap"><table><thead><tr><th>#</th><th>Atleta</th><th>Equipe</th><th>Gols</th></tr></thead><tbody>${rows.map((r, i) => `<tr><td>${i + 1}</td><td>${esc(r.name)}</td><td>${r.teamId ? esc(teamNameById(state, r.teamId) || '—') : '—'}</td><td>${r.goals}</td></tr>`).join('')}</tbody></table></div></div>`;
  }

  function disciplineView() {
    const lim = (state.cfg && state.cfg.yellowLimit) || 3;
    const rows = cardRanking(state);
    const suspended = [];
    (state.teams || []).forEach((team) => (team.roster || []).forEach((athlete) => { const info = suspensionInfo(state, athlete.id); if (info.suspended) suspended.push({ athlete, team, info }); }));
    const suspHTML = suspended.length ? `<div class="card" style="margin-bottom:16px;border-color:var(--accent)"><h2>⛔ Suspensos para o próximo jogo</h2>${suspended.map((x) => `<div class="team-row"><span>⛔</span><span><strong>${esc(x.athlete.nome)}</strong> <span class="muted">— ${esc(x.team.nome)}</span></span><span class="muted">${esc(x.info.reason)}</span></div>`).join('')}</div>` : '';
    const table = rows.length ? `<div class="card"><h2>Cartões</h2><div class="table-wrap"><table><thead><tr><th>#</th><th>Atleta</th><th>Equipe</th><th>🟨</th><th>🟥</th></tr></thead><tbody>${rows.map((r, i) => `<tr><td>${i + 1}</td><td>${esc(r.name)}</td><td>${r.teamId ? esc(teamNameById(state, r.teamId) || '—') : '—'}</td><td>${r.y || ''}</td><td>${r.r || ''}</td></tr>`).join('')}</tbody></table></div></div>` : `<div class="card"><p class="muted">Nenhum cartão registrado.</p></div>`;
    return `<p class="muted" style="margin:0 0 12px;font-size:13px">Regra de suspensão: cartão vermelho ou ${lim} amarelos = 1 jogo de suspensão.</p>${suspHTML}${table}`;
  }

  function criteriaEditorHTML(order) {
    const tail = order.filter((c) => c !== 'P');
    const pool = ['V', 'SG', 'GP', 'GC', 'CD', 'DISC'].filter((c) => !order.includes(c));
    const rows = tail.map((c, i) => `<div class="team-row"><span>${i + 2}</span><span>${esc(CRIT_LABEL[c] || c)}</span><span class="row"><button class="btn ghost sm" data-crit-move="${i}:-1" ${i === 0 ? 'disabled' : ''}>↑</button><button class="btn ghost sm" data-crit-move="${i}:1" ${i === tail.length - 1 ? 'disabled' : ''}>↓</button><button class="btn ghost sm" data-crit-remove="${i}">×</button></span></div>`).join('');
    const add = pool.length ? `<div class="row" style="margin-top:10px"><select data-crit-add-select style="flex:1">${pool.map((c) => `<option value="${esc(c)}">${esc(CRIT_LABEL[c] || c)}</option>`).join('')}</select><button class="btn ghost sm" data-crit-add>+ Incluir</button></div>` : '';
    return `<p class="muted" style="font-size:13px">Pontos é fixo em 1º; use ↑ e ↓ para reordenar os demais.</p><div class="team-row"><span>1</span><span>Pontos</span><span class="muted">fixo</span></div>${rows}${add}`;
  }
  function registrationsView() { return `<div class="card"><h2>Inscrições recebidas</h2><p class="muted">Analise as equipes enviadas pelo formulário público.</p>${registrations.length ? registrations.map((item) => `<div class="registration-row"><div><strong>${esc(item.teamName || 'Equipe')}</strong><p class="muted">${esc(item.responsible || '')} · ${esc(item.phone || '')} · ${(item.athletes || []).length} atleta(s)</p></div><span class="tag">${item.status || 'pending'}</span>${item.status === 'pending' ? `<button class="btn primary" data-approve-registration="${item.id}">Aprovar</button><button class="btn ghost" data-reject-registration="${item.id}">Recusar</button>` : ''}</div>`).join('') : '<p class="muted">Nenhuma inscrição recebida.</p>'}</div>`; }
  function auditView() { return `<div class="card"><h2>Histórico de alterações</h2>${auditRows.length ? auditRows.map((item) => `<div class="registration-row"><div><strong>${esc(item.summary || item.action)}</strong><p class="muted">${esc(item.actorEmail || '')} · ${new Date(item.createdAtMs || Date.now()).toLocaleString('pt-BR')}</p></div></div>`).join('') : '<p class="muted">Nenhuma alteração registrada.</p>'}</div>`; }
  function managementView() {
    ensureCollaborators(state);
    if (!superadmin && !isOwner(state, auth.currentUser) && !can(state, auth.currentUser, 'admin')) return '<div class="card"><p class="muted">Sem permissão para gerenciar acessos.</p></div>';
    const editable = isOwner(state, auth.currentUser) || superadmin;
    const rows = state.collaborators.map((c) => editable
      ? `<div class="row" style="padding:10px 0;border-bottom:1px solid var(--line)"><span style="flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(c.email)}</span><select data-mgr-role="${esc(c.id)}">${Object.entries(COLLAB_ROLES).map(([key, meta]) => `<option value="${esc(key)}" ${c.role === key ? 'selected' : ''}>${esc(meta.name)}</option>`).join('')}</select><button class="btn ghost" data-mgr-remove="${esc(c.id)}">Remover</button></div>`
      : `<div class="row" style="padding:10px 0;border-bottom:1px solid var(--line)"><span style="flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(c.email)}</span><span class="muted">${esc(COLLAB_ROLES[c.role]?.name || c.role)}</span></div>`
    ).join('') || '<p class="muted">Nenhum colaborador adicionado.</p>';
    return `<div class="card"><h2>Gerenciamento de acesso</h2><p class="muted">Convide pessoas para ajudar a operar este campeonato com um papel específico.</p><div style="margin-top:18px">${rows}</div>${editable ? `<div class="row" style="margin-top:12px;gap:8px"><input data-new-mgr-email placeholder="E-mail" type="email" style="flex:1"><select data-new-mgr-role>${Object.entries(COLLAB_ROLES).map(([key, meta]) => `<option value="${esc(key)}">${esc(meta.name)}</option>`).join('')}</select><button class="btn primary" data-add-mgr>+ Convidar</button></div>` : ''}</div>`;
  }
  function config() { state.branding = state.branding || {}; const criterios = state.cfg?.criterios || ['P', 'V', 'SG', 'GP']; return `<div class="card"><h2>Configurações</h2><label class="muted">Status<select data-status><option value="rascunho">Rascunho</option><option value="inscricoes">Inscrições abertas</option><option value="andamento">Em andamento</option><option value="encerrado">Encerrado</option></select></label><label class="muted">Cor principal<input type="color" data-accent value="${esc(state.branding.accent || '#2fcf6b')}"></label><button class="btn primary" data-save-config>Salvar configurações</button><button class="btn ghost" style="margin-top:8px" data-clear-results>↺ Zerar resultados</button></div><div class="card" style="margin-top:16px"><h2>Pontuação e desempate</h2><p class="muted" style="font-size:13px;margin:0 0 12px">Estas configurações valem para a fase ativa.</p><div class="row" style="flex-wrap:wrap"><label class="muted" style="flex:1;min-width:120px">Vitória<input type="number" data-win-pts value="${state.cfg?.winPts ?? 3}"></label><label class="muted" style="flex:1;min-width:120px">Empate<input type="number" data-draw-pts value="${state.cfg?.drawPts ?? 1}"></label><label class="muted" style="flex:1;min-width:120px">Derrota<input type="number" data-loss-pts value="${state.cfg?.lossPts ?? 0}"></label></div><div style="margin-top:14px"><span class="muted">Critérios de desempate (ordem)</span>${criteriaEditorHTML(criterios)}</div>${criterios.includes('DISC') ? `<div class="row" style="flex-wrap:wrap;margin-top:12px"><label class="muted" style="flex:1;min-width:160px">Cartão amarelo<input type="number" min="0" data-disc-yellow value="${state.cfg?.discYellow ?? 1}"></label><label class="muted" style="flex:1;min-width:160px">Cartão vermelho<input type="number" min="0" data-disc-red value="${state.cfg?.discRed ?? 5}"></label></div>` : ''}<label class="muted" style="margin-top:12px">Amarelos para suspensão<input type="number" min="0" data-yellow-limit value="${state.cfg?.yellowLimit || 3}"></label><button class="btn primary" style="margin-top:12px" data-save-scoring>Salvar pontuação e desempate</button></div><div class="card" style="margin-top:16px"><h2>Locais</h2>${(state.venues || []).map((venue) => `<div class="team-row"><span>📍</span><span>${esc(venue.name)}${venue.address ? ` <span class="muted">· ${esc(venue.address)}</span>` : ''}</span><button class="btn ghost" data-remove-venue="${esc(venue.id)}">Remover</button></div>`).join('') || '<p class="muted">Nenhum local cadastrado.</p>'}<div class="row" style="margin-top:12px;gap:8px"><input data-new-venue-name placeholder="Nome do local" style="flex:1"><input data-new-venue-address placeholder="Endereço (opcional)" style="flex:1"><button class="btn primary" data-add-venue>+ Adicionar</button></div></div><div class="card" style="margin-top:16px"><h2>Árbitros e mesários</h2>${(state.officials || []).map((official) => `<div class="team-row"><span>🧑‍⚖️</span><span>${esc(official.name)}${official.role ? ` <span class="muted">· ${esc(official.role)}</span>` : ''}</span><button class="btn ghost" data-remove-official="${esc(official.id)}">Remover</button></div>`).join('') || '<p class="muted">Nenhum oficial cadastrado.</p>'}<div class="row" style="margin-top:12px;gap:8px"><input data-new-official-name placeholder="Nome" style="flex:1"><input data-new-official-role placeholder="Função" style="width:140px"><button class="btn primary" data-add-official>+ Adicionar</button></div></div>`; }
  function bind() { root.querySelector('[data-pdf]')?.addEventListener('click', async () => { const button = root.querySelector('[data-pdf]'); button.disabled = true; await downloadChampionshipPDF(state); button.disabled = false; }); const status = root.querySelector('[data-status]'); if (status) status.value = state.status || 'rascunho'; root.querySelector('[data-publication]')?.addEventListener('click', () => navigate(`/publicacao/${state.id}`)); root.querySelectorAll('[data-jump]').forEach((button) => button.onclick = () => { tab = button.dataset.jump; render(); }); root.querySelectorAll('[data-category]').forEach((button) => button.onclick = async () => { switchCategory(state, button.dataset.category); tab = 'overview'; await persist(); render(); }); const addCategoryBtn = root.querySelector('[data-add-category]'); if (addCategoryBtn) addCategoryBtn.onclick = async () => { addCategory(state); await persist(); await addAudit(state.id, 'category_added', 'Categoria criada'); render(); }; root.querySelectorAll('[data-category-name]').forEach((input) => input.onchange = async () => { renameCategory(state, input.dataset.categoryName, input.value); await persist(); await addAudit(state.id, 'category_renamed', 'Categoria renomeada'); }); root.querySelectorAll('[data-remove-category]').forEach((button) => button.onclick = async () => { if (!confirm('Excluir esta categoria e suas equipes e jogos?')) return; const result = removeCategory(state, button.dataset.removeCategory); if (!result.ok) return toast(result.reason); await persist(); await addAudit(state.id, 'category_removed', 'Categoria excluída'); render(); }); const addPhaseBtn = root.querySelector('[data-add-phase]'); if (addPhaseBtn) addPhaseBtn.onclick = async () => { addPhase(state, activeCategory(state)); tab = 'fases'; await persist(); await addAudit(state.id, 'phase_added', 'Fase criada'); render(); }; root.querySelectorAll('[data-phase-name]').forEach((input) => input.onchange = async () => { renamePhase(activeCategory(state), input.dataset.phaseName, input.value); await persist(); await addAudit(state.id, 'phase_renamed', 'Fase renomeada'); }); root.querySelectorAll('[data-phase-format]').forEach((select) => select.onchange = async () => { setPhaseFormat(state, activeCategory(state), select.dataset.phaseFormat, select.value); await persist(); await addAudit(state.id, 'phase_format_changed', 'Formato da fase alterado'); render(); }); root.querySelectorAll('[data-phase-turnos]').forEach((input) => input.onchange = async () => { const category = activeCategory(state); const phase = category.phases.find((p) => p.id === input.dataset.phaseTurnos); if (!phase) return; const value = Math.max(1, Math.min(2, +input.value || 1)); if (phase.id === category.activePhaseId) { state.cfg = state.cfg || {}; state.cfg.turnos = value; } else { phase.cfg = phase.cfg || {}; phase.cfg.turnos = value; } await persist(); render(); }); root.querySelectorAll('[data-phase-ngrupos]').forEach((input) => input.onchange = async () => { const category = activeCategory(state); const phase = category.phases.find((p) => p.id === input.dataset.phaseNgrupos); if (!phase) return; const value = Math.max(1, +input.value || 2); if (phase.id === category.activePhaseId) { state.cfg = state.cfg || {}; state.cfg.nGrupos = value; } else { phase.cfg = phase.cfg || {}; phase.cfg.nGrupos = value; } await persist(); render(); }); root.querySelectorAll('[data-phase-mao-unica]').forEach((input) => input.onchange = async () => { const category = activeCategory(state); const phase = category.phases.find((p) => p.id === input.dataset.phaseMaoUnica); if (!phase) return; if (phase.id === category.activePhaseId) { state.cfg = state.cfg || {}; state.cfg.maoUnica = input.checked; } else { phase.cfg = phase.cfg || {}; phase.cfg.maoUnica = input.checked; } await persist(); render(); }); root.querySelectorAll('[data-phase-terceiro]').forEach((input) => input.onchange = async () => { const category = activeCategory(state); const phase = category.phases.find((p) => p.id === input.dataset.phaseTerceiro); if (!phase) return; if (phase.id === category.activePhaseId) { state.cfg = state.cfg || {}; state.cfg.terceiro = input.checked; } else { phase.cfg = phase.cfg || {}; phase.cfg.terceiro = input.checked; } await persist(); render(); });root.querySelectorAll('[data-switch-phase]').forEach((button) => button.onclick = async () => { switchPhase(state, activeCategory(state), button.dataset.switchPhase); tab = 'overview'; await persist(); render(); }); root.querySelectorAll('[data-remove-phase]').forEach((button) => button.onclick = async () => { if (!confirm('Excluir esta fase e todos os jogos vinculados a ela?')) return; const result = removePhase(state, activeCategory(state), button.dataset.removePhase); if (!result.ok) return toast(result.reason); await persist(); await addAudit(state.id, 'phase_removed', 'Fase excluída'); render(); }); const generatePhaseBtn = root.querySelector('[data-generate-phase]'); if (generatePhaseBtn) generatePhaseBtn.onclick = async () => { const result = generateActivePhase(state); if (!result.ok) return toast(result.reason); await persist(); await addAudit(state.id, 'phase_generated', 'Jogos da fase gerados'); render(); }; root.querySelectorAll('[data-progress-target]').forEach((select) => select.onchange = async () => { setProgressTarget(activeCategory(state), select.dataset.progressTarget, select.value); await persist(); render(); }); root.querySelectorAll('[data-progress-mode]').forEach((select) => select.onchange = async () => { setProgressMode(activeCategory(state), select.dataset.progressMode, select.value); await persist(); render(); }); root.querySelectorAll('[data-progress-count]').forEach((input) => input.onchange = async () => { setProgressCount(activeCategory(state), input.dataset.progressCount, input.value); await persist(); render(); });root.querySelectorAll('[data-approve-registration]').forEach((button) => button.onclick = async () => { const item = registrations.find((row) => row.id === button.dataset.approveRegistration); const team = { id: uid(), nome: item.teamName || 'Equipe', roster: (item.athletes || []).map((athlete) => ({ id: uid(), nome: athlete.name, numero: athlete.number || '' })) }; state.teams = [...(state.teams || []), team]; await updateRegistration(state.id, button.dataset.approveRegistration, { status: 'approved', approvedAt: Date.now(), teamId: team.id }); await persist(); await addAudit(state.id, 'registration_approved', `Inscrição aprovada: ${team.nome}`, null, team); registrations = await listRegistrations(state.id); render(); }); root.querySelectorAll('[data-reject-registration]').forEach((button) => button.onclick = async () => { await updateRegistration(state.id, button.dataset.rejectRegistration, { status: 'rejected', rejectedAt: Date.now() }); await addAudit(state.id, 'registration_rejected', 'Inscrição recusada'); registrations = await listRegistrations(state.id); render(); }); const add = root.querySelector('[data-add-team]'); if (add) add.onclick = () => { state.teams = state.teams || []; state.teams.push({ id: uid(), nome: `Equipe ${state.teams.length + 1}`, roster: [] }); render(); }; root.querySelectorAll('[data-remove-team]').forEach((button) => button.onclick = () => { state.teams = state.teams.filter((team) => team.id !== button.dataset.removeTeam); render(); }); root.querySelectorAll('[data-roster]').forEach((button) => button.onclick = () => rosterModal(button.dataset.roster)); root.querySelectorAll('[data-pick-logo]').forEach((el) => el.onclick = () => { const input = document.createElement('input'); input.type = 'file'; input.accept = 'image/*'; input.onchange = async () => { const file = input.files[0]; if (!file) return; const dataUrl = await compressPhoto(file); if (!dataUrl) return toast('Falha na imagem'); setTeamLogo(teamById(state, el.dataset.pickLogo), dataUrl); await persist(); render(); }; input.click(); }); const saveTeams = root.querySelector('[data-save-teams]'); if (saveTeams) saveTeams.onclick = async () => { root.querySelectorAll('[data-team]').forEach((input) => { const team = state.teams.find((item) => item.id === input.dataset.team); if (team) team.nome = input.value.trim() || 'Equipe'; }); await persist(); await addAudit(state.id, 'teams_updated', 'Equipes atualizadas'); render(); }; root.querySelectorAll('[data-score]').forEach((input) => input.onchange = async () => { const [matchId, field] = input.dataset.score.split(':'); const result = setScore(state, matchId, field, input.value); if (!result.ok) return; const match = state.matches.find((item) => item.id === matchId); const home = state.teams?.[match.home]?.nome || '?'; const away = state.teams?.[match.away]?.nome || '?'; await persist(); await addAudit(state.id, 'score_updated', `Placar alterado: ${home} ${result.after.hg ?? '–'} × ${result.after.ag ?? '–'} ${away}`, result.before, result.after); }); root.querySelectorAll('[data-match-ops]').forEach((button) => button.onclick = () => matchOpsModal(button.dataset.matchOps)); root.querySelectorAll('[data-apply-progress]').forEach((button) => button.onclick = async () => { const category = activeCategory(state); const phaseId = button.dataset.applyProgress; let result = applyProgression(state, category, phaseId); if (!result.ok && result.reason === 'incomplete') { if (!confirm('A fase ainda possui jogos pendentes. Avançar com a classificação atual?')) return; result = applyProgression(state, category, phaseId, { force: true }); } if (!result.ok) return toast({ 'no-target': 'Configure a fase de destino', 'target-missing': 'Fase de destino não encontrada', 'no-qualifiers': 'Ainda não há classificados definidos' }[result.reason] || 'Não foi possível classificar'); tab = 'fases'; await persist(); await addAudit(state.id, 'phase_progressed', `${result.count} classificado(s) enviados para ${esc(result.targetName)}`); render(); }); const genCrossBtn = root.querySelector('[data-gen-cross]'); if (genCrossBtn) genCrossBtn.onclick = async () => { genCross(state); await persist(); await addAudit(state.id, 'bracket_generated', 'Mata-mata gerado a partir dos grupos'); render(); }; const regenCrossBtn = root.querySelector('[data-regen-cross]'); if (regenCrossBtn) regenCrossBtn.onclick = async () => { if (!confirm('Regerar o mata-mata? O chaveamento atual será substituído.')) return; genCross(state); await persist(); await addAudit(state.id, 'bracket_generated', 'Mata-mata regerado'); render(); }; const saveConfig = root.querySelector('[data-save-config]'); if (saveConfig) saveConfig.onclick = async () => { state.status = status.value; state.branding.accent = root.querySelector('[data-accent]').value; shell.style.setProperty('--championship-accent', state.branding.accent); await persist(); await addAudit(state.id, 'config_updated', 'Configurações atualizadas'); render(); }; function captureScoring() { state.cfg = state.cfg || {}; state.cfg.winPts = +root.querySelector('[data-win-pts]').value || 0; state.cfg.drawPts = +root.querySelector('[data-draw-pts]').value || 0; state.cfg.lossPts = +root.querySelector('[data-loss-pts]').value || 0; const discYellowInput = root.querySelector('[data-disc-yellow]'); if (discYellowInput) state.cfg.discYellow = Math.max(0, +discYellowInput.value || 0); const discRedInput = root.querySelector('[data-disc-red]'); if (discRedInput) state.cfg.discRed = Math.max(0, +discRedInput.value || 0); state.cfg.yellowLimit = Math.max(0, +root.querySelector('[data-yellow-limit]').value || 0); } root.querySelectorAll('[data-crit-move]').forEach((button) => button.onclick = async () => { captureScoring(); const [i, dir] = button.dataset.critMove.split(':').map(Number); state.cfg.criterios = critMove(state.cfg.criterios || ['P', 'V', 'SG', 'GP'], i, dir); await persist(); render(); }); root.querySelectorAll('[data-crit-remove]').forEach((button) => button.onclick = async () => { captureScoring(); state.cfg.criterios = critRemove(state.cfg.criterios || ['P', 'V', 'SG', 'GP'], +button.dataset.critRemove); await persist(); render(); }); const critAddBtn = root.querySelector('[data-crit-add]'); if (critAddBtn) critAddBtn.onclick = async () => { const select = root.querySelector('[data-crit-add-select]'); if (!select || !select.value) return; captureScoring(); state.cfg.criterios = critAdd(state.cfg.criterios || ['P', 'V', 'SG', 'GP'], select.value); await persist(); render(); }; const saveScoringBtn = root.querySelector('[data-save-scoring]'); if (saveScoringBtn) saveScoringBtn.onclick = async () => { captureScoring(); await persist(); await addAudit(state.id, 'scoring_updated', 'Pontuação e desempate atualizados'); render(); }; const clearBtn = root.querySelector('[data-clear-results]'); if (clearBtn) clearBtn.onclick = async () => { if (!confirm('Zerar todos os placares e o chaveamento desta fase?')) return; clearResults(state); await persist(); await addAudit(state.id, 'results_cleared', 'Resultados zerados'); render(); }; const generate = root.querySelector('[data-generate]'); if (generate) generate.onclick = async () => { const result = generateActivePhase(state); if (!result.ok) return toast(result.reason); await persist(); await addAudit(state.id, 'games_generated', 'Jogos gerados'); render(); }; root.querySelectorAll('[data-tie-score]').forEach((input) => input.onchange = async () => { const [tieId, field] = input.dataset.tieScore.split(':'); const tie = findTie(state.bracket, tieId); if (!tie) return; tie[field] = input.value === '' ? null : Number(input.value); advanceBracket(state.bracket, state.cfg); await persist(); await addAudit(state.id, 'tie_score_updated', 'Placar do chaveamento atualizado'); render(); }); const addVenueBtn = root.querySelector('[data-add-venue]'); if (addVenueBtn) addVenueBtn.onclick = async () => { const nameInput = root.querySelector('[data-new-venue-name]'); const addrInput = root.querySelector('[data-new-venue-address]'); const result = addVenue(state, { name: nameInput.value, address: addrInput.value }); if (!result.ok) return toast(result.reason); await persist(); await addAudit(state.id, 'venue_added', `Local adicionado: ${result.venue.name}`); render(); }; root.querySelectorAll('[data-remove-venue]').forEach((button) => button.onclick = async () => { const result = removeVenue(state, button.dataset.removeVenue); if (!result.ok) return; await persist(); await addAudit(state.id, 'venue_removed', 'Local removido'); render(); }); const addOfficialBtn = root.querySelector('[data-add-official]'); if (addOfficialBtn) addOfficialBtn.onclick = async () => { const nameInput = root.querySelector('[data-new-official-name]'); const roleInput = root.querySelector('[data-new-official-role]'); const result = addOfficial(state, { name: nameInput.value, role: roleInput.value }); if (!result.ok) return toast(result.reason); await persist(); await addAudit(state.id, 'official_added', `Oficial adicionado: ${result.official.name}`); render(); }; root.querySelectorAll('[data-remove-official]').forEach((button) => button.onclick = async () => { const result = removeOfficial(state, button.dataset.removeOfficial); if (!result.ok) return; await persist(); await addAudit(state.id, 'official_removed', 'Oficial removido'); render(); }); const addMgrBtn = root.querySelector('[data-add-mgr]'); if (addMgrBtn) addMgrBtn.onclick = async () => { const emailInput = root.querySelector('[data-new-mgr-email]'); const roleSelect = root.querySelector('[data-new-mgr-role]'); const result = inviteManager(state, auth.currentUser, { email: emailInput.value, role: roleSelect.value }); if (!result.ok) return toast(result.reason); await persist(); await addAudit(state.id, 'collaborator_invited', `Acesso concedido: ${result.collaborator.email}`); render(); }; root.querySelectorAll('[data-mgr-role]').forEach((select) => select.onchange = async () => { const result = changeManagerRole(state, auth.currentUser, select.dataset.mgrRole, select.value); if (!result.ok) { toast(result.reason); return render(); } await persist(); await addAudit(state.id, 'collaborator_role_changed', 'Papel de colaborador alterado'); render(); }); root.querySelectorAll('[data-mgr-remove]').forEach((button) => button.onclick = async () => { if (!confirm('Remover o acesso deste colaborador?')) return; const result = removeManager(state, auth.currentUser, button.dataset.mgrRemove); if (!result.ok) return toast(result.reason); await persist(); await addAudit(state.id, 'collaborator_removed', 'Acesso de colaborador removido'); render(); }); }
  render();
}


